# compute_standard_revenue.py

def compute_standard_revenue(prices, quantities):
    """Compute total revenue given lists of prices and quantities."""
    if len(prices) != len(quantities):
        raise ValueError("prices and quantities must have same length")
    return sum(p * q for p, q in zip(prices, quantities))

if __name__ == "__main__":
    # example usage
    prices = [10.0, 20.0, 5.5]
    quantities = [3, 2, 10]
    total = compute_standard_revenue(prices, quantities)
    print(f"Total revenue: {total}")

